// Gabarits des pages statiques : méthode, axes, familles d'idées, partis, auteurs. Le navigateur ne charge jamais ce
// fichier : scripts/build-pages.mjs l'évalue après data.js, engine.mjs et app.mjs, dont il reprend les données et les
// fonctions de rendu. Un lien vers une page statique s'écrit depuis la racine du site (« familles/ ») ; la génération le
// rend relatif à la page qui le contient, et « #questionnaire » ou « #accueil » mènent à l'application.

// Les familles sont présentées par ordre alphabétique, qui ne suggère aucun axe gauche-droite.
const familiesByName=D.families.slice().sort((x,y)=>x.name.localeCompare(y.name,'fr',{sensitivity:'base'}));
const familyName=f=>`<a href="familles/${f.id}/">${e(f.name)}</a>`;
const PARTIES_N=D.parties.parties.length,AUTHORS_N=D.references.thinkers.length;
const axisNumber=a=>String(axes.indexOf(a)+1).padStart(2,'0');
const plural2=(n,one,many)=>`${n} ${n>1?many:one}`;

// En-tête commun aux pages de référence, puis leurs rubriques en onglets (SECTIONS, dans app.mjs), comme les vues du bilan.
// Le titre propre à chaque page (h1) suit les onglets, à la place du titre de vue du bilan.
function areaHead(here,path){return `<div class="page-head"><div class="result-title"><div class="eyebrow">Méthode et repères</div><p class="area-title">Comprendre le bilan</p><p>Le calcul, les ${AXES_N} axes et leurs arguments, les repères des ${familyCount} familles d’idées, les partis et les auteurs cités : tout ce qui sert à établir le bilan, consultable sans répondre au questionnaire.</p></div></div><nav class="tabs" aria-label="Rubriques">${SECTIONS.map(([p,label])=>`<a class="tab${here===p?' active':''}" href="${p}"${path===p?' aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
const pageTitle=(icon,title,lead='',eyebrow='')=>`<div class="section-intro stacked">${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}${titled(icon,title,'','h1')}${lead?`<p>${lead}</p>`:''}</div>`;
const SEE='<span class="family-toggle" aria-hidden="true"><span class="ft-open">Voir</span><svg viewBox="0 0 12 12"><path d="M4.5 2l4 4-4 4"/></svg></span>';
// Repère d'une famille sur un axe, au format des positions de la vue d'ensemble du bilan : intitulé et valeur, ligne de
// 0 à 10, pôles. Un axe sans repère est dit non défini. La famille mise en avant est en encre, les autres en gris.
function referenceMini(href,label,a,target,ink){
 const has=typeof target==='number',read=has?`${fmt(target)} sur 10, ${lcFirst(axisReading(a,target).short)}`:'non défini';
 return `<a class="axis-mini ref-mini${has?'':' undefined'}" href="${href}" aria-label="${e(label)} : ${e(read)}"><span class="axis-mini-head"><span>${e(label)}</span><span class="axis-mini-score">${has?fmt(target):'—'}</span></span><span class="axis-track" aria-hidden="true"><span class="axis-mid"></span>${has?`<span class="${ink?'gap-ref':'axis-ref'}" style="left:${target*10}%"></span>`:''}</span><span class="axis-poles"><span>${e(a.low)}</span><span>${e(a.high)}</span></span></a>`;
}
// Invitation commune au bas des pages statiques.
function staticCta(){return `<aside class="panel page-cta" aria-labelledby="cta-titre">${titled('ballot','Où vous situez-vous ?',' id="cta-titre"')}<p>Répondez aux ${QUESTIONS_N} propositions : le bilan situe vos positions sur les ${AXES_N} axes et mesure votre écart avec ${familyCount} familles d’idées, sans consigne de vote. Vos réponses restent dans votre navigateur.</p><div class="actions"><a class="btn primary" href="#questionnaire">Répondre au questionnaire →</a></div></aside>`;}
// Lien vers la page voisine (axe ou famille), en bas de page.
const step=(href,label,name)=>href?`<a class="axis-step" href="${href}"><small>${label}</small><span>${name}</span></a>`:'<span></span>';

const MODEL_NOTE='Ces valeurs sont une modélisation éditoriale de courants d’idées, pas des scores mesurés de partis ni des réponses attribuées à leurs membres.';

// Page Méthode : calcul, lecture des scores, limites, confidentialité et sources de la méthode.
function methodPage(){return `${pageTitle('compass','Comment le bilan est calculé','Ce que le bilan mesure, et ce qu’il ne mesure pas.')}<article class="method-sheet"><section>${blockTitle('axes',`${AXES_N} axes, sans moyenne gauche-droite`)}<p>Les dimensions retenues distinguent redistribution, organisation de l’économie, travail, budget, autonomie personnelle, libertés, immigration, intégration, expression religieuse, méthodes antidiscriminatoires, écologie, Europe, commerce, alliances, effort de défense, soutien à un pays agressé, contre-pouvoirs, exécutif, participation et territoires. Elles peuvent être corrélées ; leur indépendance statistique n’est pas démontrée.</p></section><section>${blockTitle('propositions',`${PER_AXIS} propositions par axe`)}<p>Chaque axe comporte ${PER_AXIS/2} propositions dont l’accord conduit vers le pôle 0 et ${PER_AXIS/2} dont l’accord conduit vers le pôle 10. Les ${DEGREES} réponses sont codées −2, −1, 0, +1, +2. « Je ne sais pas » est exclu du calcul, jamais remplacé par une valeur neutre.</p><div class="formula">score d’une réponse = 5 + 2,5 × orientation × accord<br>score de l’axe = moyenne des réponses de fond</div><p>L’orientation vaut −1 ou +1 selon la proposition. Il faut 2 réponses de fond au minimum pour afficher un axe. Les scores sont affichés à une décimale pour rendre le calcul lisible ; cette précision n’est pas une mesure de certitude.</p><p>Une moyenne proche de 5 peut traduire des réponses neutres ou des arbitrages opposés. Un signal « Réponses contrastées » apparaît lorsque l’écart entre deux contributions d’un axe atteint 7,5 points. Ce signal invite à relire les réponses ; il ne signifie pas une incohérence.</p></section><section>${blockTitle('map','Une lecture globale à deux niveaux')}<p>La petite carte à deux dimensions projette la moyenne de redistribution, économie et travail sur l’axe horizontal, et la moyenne d’autonomie personnelle, immigration et intégration sur l’axe vertical. Chaque coordonnée demande 2 axes renseignés sur 3. Cette projection est volontairement partielle. Chaque coordonnée est décrite en trois tranches : moins de 3,5, de 3,5 à 6,5, plus de 6,5. Les familles d’idées y sont placées avec la même règle à partir de leurs repères ; celles qui ne définissent pas 2 des 3 axes d’une coordonnée n’apparaissent pas.</p><p>La synthèse compare aussi votre profil à ${familyCount} familles d’idées. Leurs coordonnées sont des choix éditoriaux explicites, inspirés de textes doctrinaux et de programmes consultés, pas des données d’enquête sur les partis. Quand ces textes ne traitent pas un sujet, des déclarations publiques datées de leurs responsables, citées mot pour mot, servent de repère provisoire en attendant les programmes de 2027 ; elles sont signalées comme telles. Certaines coordonnées restent indéfinies pour ne pas inventer une doctrine commune sur tous les sujets. Les repères des familles peuvent évoluer d’une version à l’autre : les modifier ne change ni vos réponses ni vos scores, et des réponses exportées restent importables.</p><div class="formula">écart = Σ (importance × |votre score − repère|) / Σ importance</div><p>Seuls les axes renseignés des deux côtés sont comparés. Importance : secondaire = 1, important = 2, déterminant = 3. Les priorités modifient les proximités, jamais les scores de vos axes. Le nombre d’axes comparés est affiché pour chaque famille : les profils n’ayant pas le même périmètre, leur classement reste indicatif.</p><p>Il faut au moins ${MIN_COMMON_AXES} axes communs pour afficher une comparaison. La synthèse globale exige ${MIN_SYNTHESIS_AXES} axes mesurés et les deux coordonnées de projection. Deux écarts distants de moins de 0,35 point sont présentés ensemble ; si le meilleur écart dépasse 3 points, le résultat est « Profil transversal ». Ces seuils sont des conventions de cette version, sans calibration statistique.</p></section><section>${blockTitle('phrase','Des scores traduits en phrases')}<p>Le bilan décrit chaque axe selon sa distance au milieu de l’échelle (5). À plus de ${READING.strong} points du milieu : préférence nette pour le pôle le plus proche. De plus de ${READING.middle} à ${READING.strong} points : préférence modérée. À ${READING.middle} point ou moins : avis partagés si au moins une réponse va vers chaque pôle, position intermédiaire sinon. Les positions les plus marquées regroupent d’abord les préférences nettes, puis les préférences modérées ; dans chaque groupe, les sujets jugés déterminants passent en premier.</p><p>Pour les familles, deux écarts moyens distants de moins de ${fmtExact(READING.tie)} point sont présentés à égalité ; de ${fmtExact(READING.tie)} à moins de ${READING.clear} point, la première famille arrive en tête de peu ; à partir de ${READING.clear} point, elle se détache nettement. Sur un axe, un accord correspond à ${READING.agree} point d’écart au plus avec le repère, un écart net à plus de ${READING.diverge} points. Sur l’échelle des proximités, un écart moyen d’au plus ${READING.agree} point est qualifié de très proche, d’au plus ${READING.diverge} points de proche, d’au plus ${READING.transversal} points de plutôt éloigné, et d’éloigné au-delà. Ces seuils de lecture sont des conventions de cette version, sans calibration statistique ; ils ne modifient aucun score.</p></section><section>${blockTitle('gauge','Ce que signifie un score extrême')}<p>Chaque axe est tracé comme une ligne qui va de son pôle 0 à son pôle 10, avec le milieu de l’échelle marqué. Les pôles sont propres à chaque axe : il n’existe pas de sens « gauche vers droite » commun aux ${AXES_N} lignes. Un score extrême sur un axe ne suffit pas à attribuer l’étiquette d’extrême gauche ou d’extrême droite. La position sur les contre-pouvoirs reste décrite séparément des orientations économiques et culturelles.</p></section><section>${blockTitle('flask','Un outil indicatif, encore à éprouver')}<p>Les ${QUESTIONS_N} propositions sont originales. Elles n’ont pas fait l’objet d’un étalonnage représentatif, d’une analyse factorielle, ni d’une validation de fidélité ou de biais. Certains sujets peuvent être consensuels et certaines formulations sensibles au contexte. Les références académiques justifient l’intérêt de plusieurs dimensions ; elles ne valident pas ce questionnaire.</p><p>Les thèses citées sous chaque axe éclairent ses deux pôles ; elles ne valident pas la mesure. Un auteur cité à un pôle d’un axe peut se trouver à l’autre pôle d’un autre axe, et aucune réponse ne lui est imputée.</p><p>L’outil a été élaboré avec l’aide d’une intelligence artificielle. Les choix éditoriaux relèvent de l’éditeur, qui les a validés, et les citations ont été vérifiées mot pour mot sur leurs sources archivées. Le bilan est calculé dans votre navigateur par un programme fixe : aucune IA n’intervient dans ce calcul ni ne reçoit vos réponses.</p></section><section>${blockTitle('ballot','Une aide au choix, sans consigne de vote')}<p>Le site est indépendant : il n’a de lien ni avec les pouvoirs publics, ni avec les autorités électorales, ni avec les partis. L’outil compare vos réponses à ${familyCount} familles d’idées, pas à des candidats. Il ne recommande aucun vote, n’affiche aucun pourcentage de compatibilité et ne publie aucune statistique sur les réponses.</p></section><section>${blockTitle('device','Vos réponses restent sur cet appareil')}<p>L’application ne demande ni nom ni adresse électronique. Les réponses sont calculées et conservées dans le stockage local de votre navigateur. Aucun service d’analyse, de publicité ou d’IA ne reçoit les réponses. Le site est hébergé ; cette promesse concerne les réponses au questionnaire, pas les journaux techniques ordinaires de son hébergement.</p><p>Vous pouvez exporter vos réponses dans un fichier JSON, le réimporter sur un autre navigateur, imprimer le résultat ou supprimer vos réponses. Effacer les données du navigateur supprime aussi les réponses enregistrées.</p><div class="actions"><a class="btn" href="#accueil">Gérer mes réponses depuis l’accueil →</a></div></section><section>${blockTitle('archive','Les sources')}${D.references.methods.map(s=>`<a class="source-link" href="${url(s.url)}" target="_blank" rel="noopener noreferrer">${e(s.title)} · ${s.year} ↗<small>${e(s.summary)}</small></a>`).join('')}<p>Les repères chiffrés de chaque famille d’idées et ses textes de référence sont présentés dans sa page, depuis la rubrique <a href="familles/">Familles d’idées</a>. Ces textes sont des repères de lecture, pas une validation des coordonnées choisies.</p>
 </section><section>${blockTitle('calendar','Version et mises à jour')}<p>Version ${e(D.version)}, cadre français. Les repères des familles d’idées et la liste des partis sont mis à jour à mesure que les candidatures et les programmes de 2027 sont connus. Dernière mise à jour : ${UPDATED}.</p></section></article>`;}

// Liste des axes, groupés par thème.
function axesPage(){
 const card=a=>`<a class="axis-card-link" href="axes/${a.id}/"><span class="axis-card-head"><span class="axis-num">${axisNumber(a)}</span><span class="axis-card-title"><span class="axis-card-name"><span class="axis-row-name">${e(a.name)}</span></span><span class="axis-reading">${e(a.description)}</span></span><span class="axis-card-scale">${axisTrack()}<span class="axis-poles"><span>${e(a.low)}</span><span>${e(a.high)}</span></span></span>${SEE}</span></a>`;
 return `${pageTitle('axes',`Les ${AXES_N} axes du questionnaire`,`Chaque axe va d’un pôle 0 à un pôle 10 et compte ${PER_AXIS} propositions. Les pôles sont propres à chaque axe : il n’existe pas de sens « gauche vers droite » commun aux ${AXES_N} lignes. La page de chaque axe présente ses propositions, les arguments des deux pôles et les repères des familles d’idées.`)}${Object.entries(groups).map(([id,g])=>`<section class="axis-group ${toneOf(id)}" aria-labelledby="theme-${id}"><h2 class="axis-group-title" id="theme-${id}"><span>${g.number}</span>${e(g.name)}</h2>${axes.filter(a=>a.group===id).map(card).join('')}</section>`).join('')}`;
}

// Page d'un axe : définition, pôles, propositions, arguments des deux pôles, repères de toutes les familles.
function axisPage(a){
 const i=axes.indexOf(a),tone=toneOf(a.group),defined=familiesByName.filter(f=>typeof f.positions[a.id]==='number').length;
 const propositions=a.questions.map(q=>{const [pole,end]=q.direction>0?[a.high,10]:[a.low,0];return `<li><span class="prop-body"><span class="prop-text">${nbsp(q.text)}</span><span class="prop-context">${nbsp(q.context)}</span></span><span class="prop-pole"><span class="arg-pole-end">${end}</span><span>${nbsp(`L’accord conduit vers « ${pole} »`)}</span></span></li>`;}).join('');
 const near=(b,label)=>step(b&&`axes/${b.id}/`,label,b&&`${axisNumber(b)} · ${e(b.name)}`);
 const count=defined===familyCount?`les ${familyCount} familles définissent cet axe`:`${defined} familles sur ${familyCount} définissent cet axe`;
 return `<div class="${tone}">${pageTitle('axes',e(a.name),'',`Axe ${axisNumber(a)} sur ${AXES_N} · ${e(groups[a.group].name)}`)}</div><article class="sheet ${tone}"><div class="axis-span"><span class="axis-span-pole"><span class="arg-pole-end">0</span>${e(a.low)}</span>${axisTrack()}<span class="axis-span-pole high">${e(a.high)}<span class="arg-pole-end">10</span></span></div><div class="axis-card-top"><section>${blockTitle('compass','Ce que mesure cet axe')}<p class="axis-desc">${nbsp(a.description)}</p></section><section>${blockTitle('gauge','Comment l’axe est mesuré')}<p class="axis-note">Chaque réponse place un point sur l’axe ; le score de l’axe est la moyenne des réponses de fond. « Je ne sais pas » est exclu du calcul.</p></section></div><section>${blockTitle('propositions',`Les ${a.questions.length} propositions du questionnaire`)}<ol class="prop-list">${propositions}</ol></section>${argumentsBlock(a)}<section>${blockTitle('families','Repères des familles d’idées',count)}<p class="axis-note axis-lead">${defined<familyCount?'Les autres ne le tranchent pas dans leurs textes de référence. ':''}${MODEL_NOTE}</p><div class="ref-minis">${familiesByName.map(f=>referenceMini(`familles/${f.id}/`,f.name,a,f.positions[a.id],false)).join('')}</div></section></article><nav class="axis-steps" aria-label="Axes voisins">${near(axes[i-1],'Axe précédent')}${near(axes[i+1],'Axe suivant')}</nav>`;
}

// Liste des familles d'idées.
function familiesPage(){
 const card=f=>{const n=Object.keys(f.positions).length,refs=f.sources.filter(s=>!s.provisional).length;return `<a class="family-card family-link" href="familles/${f.id}/"><span class="family-head"><span class="family-title"><h2>${e(f.name)}</h2><span class="family-meta">${n} axes définis sur ${AXES_N} · ${plural2(refs,'texte de référence','textes de référence')}</span><span class="family-link-desc">${e(f.description)}</span></span>${SEE}</span></a>`;};
 return `${pageTitle('families',`Les ${familyCount} familles d’idées`,`Le bilan compare vos réponses à ${familyCount} familles d’idées, présentées ici par ordre alphabétique.`)}<div class="static-text"><p>Les familles d’idées ne sont pas des partis. Pour fixer leurs repères, la rédaction s’appuie sur des textes de référence : programmes, textes doctrinaux, rapports. Quand l’un de ces textes émane d’un parti, ce parti est cité. Cela ne signifie ni qu’il se résume à cette famille, ni qu’il est le seul à s’en réclamer.</p><p>Des textes d’autres partis ont ensuite été comparés aux repères des familles. Un texte est cité comme texte comparé lorsque, sur chaque axe qu’il aborde parmi ceux que la famille définit, sa position reste à ${READING.diverge} points au plus du repère. Il n’a pas servi à fixer ces repères.</p></div><div class="family-list">${familiesByName.map(card).join('')}</div>`;
}

// Page d'une famille : repères sur chaque axe, textes de référence et sources, partis cités.
function familyPage(f){
 const i=familiesByName.indexOf(f),defined=axes.filter(a=>a.id in f.positions).length;
 const isReference=p=>f.sources.some(s=>s.party===p.id),reference=D.parties.parties.filter(isReference),compared=D.parties.parties.filter(p=>!isReference(p)&&(f.compared??[]).some(t=>t.party===p.id));
 const partyList=list=>`<ul class="party-chips">${list.map(p=>`<li><a href="partis/#parti-${e(p.id)}">${e(p.name)}</a>${p.acronym?` <span class="party-acronym">${e(p.acronym)}</span>`:''}</li>`).join('')}</ul>`;
 const positions=`<div class="axes-overview-grid">${Object.entries(groups).map(([id,g])=>`<div class="axis-group ${toneOf(id)}"><h3 class="axis-group-title"><span>${g.number}</span>${e(g.name)}</h3>${axes.filter(a=>a.group===id).map(a=>referenceMini(`axes/${a.id}/`,a.shortName,a,f.positions[a.id],true)).join('')}</div>`).join('')}</div>`;
 const parties=`${reference.length?`<p class="static-sub">Partis dont un texte sert de référence</p>${partyList(reference)}`:''}${compared.length?`<p class="static-sub">Partis dont un texte a été comparé</p>${partyList(compared)}`:''}${reference.length||compared.length?'':'<p class="axis-note">Aucun texte de parti n’est cité pour cette famille.</p>'}<p class="axis-note">Quand un texte de référence émane d’un parti, ce parti est cité. Cela ne signifie ni qu’il se résume à cette famille, ni qu’il est le seul à s’en réclamer. Un texte comparé n’a pas servi à fixer les repères.</p>`;
 const near=(g,label)=>step(g&&`familles/${g.id}/`,label,g&&e(g.name));
 return `${pageTitle('families',e(f.name),'','Famille d’idées')}<article class="sheet"><section>${blockTitle('idea','Le courant en bref')}<p class="axis-desc">${nbsp(f.description)}</p></section><section>${blockTitle('axes','Repères axe par axe',`${defined} axes définis sur ${AXES_N}`)}<p class="axis-note axis-lead">${MODEL_NOTE} Les axes non définis ne participent pas à la comparaison.</p>${positions}</section><section>${blockTitle('archive','Textes de référence et sources')}<div class="static-sources">${sourceGroups(f)}</div></section><section>${blockTitle('families','Partis cités')}${parties}</section></article><nav class="axis-steps" aria-label="Familles voisines">${near(familiesByName[i-1],'Famille précédente')}${near(familiesByName[i+1],'Famille suivante')}</nav>`;
}

// Tableau commun aux partis et aux auteurs : une ligne par entrée, la première cellule en titre. Sur téléphone, chaque ligne
// devient une fiche dont les cellules reprennent l'intitulé de leur colonne.
function dataTable(columns,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${columns.map(c=>`<th scope="col">${c}</th>`).join('')}</tr></thead><tbody>${rows.map(({id,cells})=>`<tr${id?` id="${id}"`:''}>${cells.map((c,k)=>k?`<td data-label="${e(columns[k])}">${c}</td>`:`<th scope="row">${c}</th>`).join('')}</tr>`).join('')}</tbody></table></div>`;}

// Catalogue des partis : critère d'inclusion, candidature et rattachement aux familles d'idées.
function partiesPage(){
 const status=Object.fromEntries(D.parties.parties.map(p=>[p.id,{reference:D.families.filter(f=>f.sources.some(s=>s.party===p.id)),compared:D.families.filter(f=>(f.compared??[]).some(t=>t.party===p.id))}]));
 const basisLabel={assemblee:'Assemblée nationale','parlement-europeen':'Parlement européen','presidentielle-2027':'Présidentielle 2027'};
 const link=(href,text)=>href?`<a href="${url(href)}" target="_blank" rel="noopener noreferrer">${text}</a>`:text;
 const familyCell=p=>{const st=status[p.id];return [st.reference.length?`Texte de référence : ${st.reference.map(familyName).join(', ')}`:'',st.compared.length?`Texte comparé : ${st.compared.map(familyName).join(', ')}`:''].filter(Boolean).join('<br>')||`<span class="muted">${e(p.unmodelled)}</span>`;};
 const row=p=>{const c=p.candidate,name=`<span class="cell-title">${e(p.name)}</span>${p.acronym?` <span class="cell-tag">${e(p.acronym)}</span>`:''}`;return {id:`parti-${e(p.id)}`,cells:[`${link(p.url,name)}${p.territory?`<small>${e(p.territory)}</small>`:''}`,p.basis.map(b=>`<span class="party-basis">${link(b.evidence,basisLabel[b.type])}${b.toVerify?'<sup>*</sup>':''}</span>`).join(''),c?(c.own?e(c.name):`Soutien à ${e(c.name)}${c.party?` (${e(partyById[c.party].acronym??partyById[c.party].name)})`:''}`):'—',familyCell(p)]};};
 const table=list=>dataTable(['Parti','Critère d’inclusion','Candidature 2027','Famille d’idées'],list.slice().sort((a,b)=>a.name.localeCompare(b.name,'fr',{sensitivity:'base'})).map(row));
 const national=D.parties.parties.filter(p=>p.scope==='national'),local=D.parties.parties.filter(p=>p.scope!=='national');
 const [y,m,d]=D.parties.asOf.split('-').map(Number),asOf=dateFr(new Date(y,m-1,d));
 const withReference=D.parties.parties.filter(p=>status[p.id].reference.length).length,withCompared=D.parties.parties.filter(p=>!status[p.id].reference.length&&status[p.id].compared.length).length;
 return `${pageTitle('ballot',`Les ${PARTIES_N} partis du catalogue`,'Les familles d’idées ne sont pas des partis. Ce catalogue indique, pour chaque parti, si l’un de ses textes sert de référence à une famille d’idées ou lui a été comparé.')}<div class="static-text"><p>Les partis du catalogue répondent au critère suivant, au ${asOf} : ${e(lcFirst(D.parties.criterion))} La liste est établie à partir des données ouvertes de l’Assemblée nationale et du Parlement européen et d’articles de presse ; chaque critère renvoie à sa source. ${withReference} partis sur ${D.parties.parties.length} ont un texte de référence et ${withCompared} un texte comparé ; pour les autres, la raison de l’absence est indiquée.</p></div><article class="sheet"><section>${blockTitle('ballot','Partis nationaux',`${national.length} partis`)}${table(national)}</section><section>${blockTitle('map','Partis régionaux et ultramarins',`${local.length} partis`)}${table(local)}</section><p class="axis-note">* Critère établi à partir d’une source unique ou de Wikipédia, à confirmer.</p></article>`;
}

// Auteurs cités sous les axes, par ordre alphabétique des noms, avec les axes où chacun apparaît.
function authorsPage(){
 const key=t=>(t.name.includes(' de ')?t.name.split(' de ').pop():t.name.split(' ').pop());
 const list=D.references.thinkers.slice().sort((x,y)=>key(x).localeCompare(key(y),'fr',{sensitivity:'base'})||x.name.localeCompare(y.name,'fr'));
 const axesOf=t=>axes.filter(a=>D.references.arguments.some(x=>x.axis===a.id&&x.authors.includes(t.id))).map(a=>`<a href="axes/${a.id}/">${e(a.shortName)}</a>`);
 return `${pageTitle('authors',`Les ${list.length} auteurs cités`)}<div class="static-text"><p>Sous chaque axe, des thèses d’auteurs éclairent les deux pôles : une ou deux mises en avant de chaque côté, parfois complétées par d’autres lectures. Elles ne modifient ni vos réponses ni vos scores.</p><p>Sont retenus des chercheurs, des intellectuels et des penseurs dont la pensée ou les écrits ont été reconnus par leurs pairs, et qui ne sont associés ni à une théorie du complot, ni à la désinformation, ni à des propos extrémistes, racistes ou antisémites, ni à une condamnation ou à un scandale public. Les auteurs classiques sont lus pour leur œuvre. Les responsables politiques du passé figurent lorsque leur pensée éclaire un axe ; les candidats et les dirigeants en fonction n’y figurent pas, leurs positions apparaissant dans les textes de référence des familles d’idées. Les thèses sont des synthèses de la rédaction ; les citations, en français, reproduisent mot pour mot le texte de l’auteur ou sa traduction publiée, et chaque source est conservée dans les archives de l’outil.</p></div><article class="sheet"><section>${blockTitle('authors','Auteurs cités',`${list.length} auteurs, par ordre alphabétique`)}${dataTable(['Auteur','Discipline et institution','Axes où il est cité'],list.map(t=>({cells:[`<span class="cell-title">${e(t.name)}</span>`,e([t.discipline,t.role].filter(Boolean).join(' · '))+(t.years?`<small>${e(t.years)}</small>`:''),listFr(axesOf(t))]})))}</section></article>`;
}

// Toutes les pages statiques, dans l'ordre du plan du site : adresse, rubrique, titre, description, contenu.
function staticPages(){
 return [
  {path:'methode/',section:'methode/',body:methodPage(),
   title:'Méthode : calcul du bilan, seuils de lecture et sources · Avant l’isoloir',
   description:`Comment Avant l’isoloir situe vos positions sur ${AXES_N} axes et mesure votre écart avec ${familyCount} familles d’idées pour la présidentielle 2027 : formules, seuils de lecture, limites de l’outil et sources.`},
  {path:'axes/',section:'axes/',body:axesPage(),
   title:`Les ${AXES_N} axes du questionnaire : propositions et arguments · Avant l’isoloir`,
   description:`Redistribution, immigration, Europe, écologie, institutions… Les ${AXES_N} axes d’Avant l’isoloir pour la présidentielle 2027, leurs ${QUESTIONS_N} propositions, les arguments de ${AUTHORS_N} auteurs et les repères de ${familyCount} familles d’idées.`},
  ...axes.map(a=>({path:`axes/${a.id}/`,section:'axes/',body:axisPage(a),
   title:`${a.name} : propositions, arguments et repères · Avant l’isoloir`,
   description:`${a.low} ou ${lcFirst(a.high)} : les ${a.questions.length} propositions d’Avant l’isoloir sur l’axe « ${a.name} », les thèses de ${new Set(D.references.arguments.filter(x=>x.axis===a.id).flatMap(x=>x.authors)).size} auteurs aux deux pôles et les repères de ${familyCount} familles d’idées.`})),
  {path:'familles/',section:'familles/',body:familiesPage(),
   title:`Les ${familyCount} familles d’idées : repères et textes de référence · Avant l’isoloir`,
   description:`Les ${familyCount} familles d’idées auxquelles Avant l’isoloir compare vos réponses pour la présidentielle 2027 : leurs repères sur ${AXES_N} axes, leurs textes de référence et les partis cités.`},
  ...familiesByName.map(f=>({path:`familles/${f.id}/`,section:'familles/',body:familyPage(f),
   title:`${f.name} : repères et textes de référence · Avant l’isoloir`,
   description:`${f.description} Repères sur ${Object.keys(f.positions).length} axes, textes de référence et partis cités.`})),
  {path:'partis/',section:'partis/',body:partiesPage(),
   title:`Les ${PARTIES_N} partis du catalogue : critère et familles d’idées · Avant l’isoloir`,
   description:`Les ${PARTIES_N} partis retenus par Avant l’isoloir pour la présidentielle 2027 : critère d’inclusion, candidature et textes rattachés aux familles d’idées.`},
  {path:'auteurs/',section:'auteurs/',body:authorsPage(),
   title:`Les ${AUTHORS_N} auteurs cités : arguments des deux pôles · Avant l’isoloir`,
   description:`Les ${AUTHORS_N} chercheurs et penseurs dont Avant l’isoloir cite les thèses aux deux pôles de ses ${AXES_N} axes, et les critères de leur choix.`}];
}
